\begin{theorem}[Vanishing of finite monodromy orbits]\hypertarget{tag-02RF}{}\label{night:P2.5}\label{stmt:P2.5}
\StatementRecord{night:P2.5}{proved}{02RF}{the definitions and constructions stated in the proof}

The global monodromy on $\Lambda_\Q/\Q\widehat\delta$ has no nonzero vector with finite orbit.
\end{theorem}
\begin{proof}
\begin{enumerate}[label=\arabic*.,leftmargin=*]
\item In coordinates $(g,u,w)$, a cusp unipotent has nilpotent part $N=E_{32}$. The two finite homology generators are
\[
 A_1=\begin{pmatrix}1&0&0&0\\6&0&1&0\\-6&-1&-1&0\\-2&1&0&1\end{pmatrix},\qquad
 A_2=\begin{pmatrix}1&0&0&0\\0&0&-1&0\\-6&1&0&0\\3&0&1&1\end{pmatrix}.
\]
A vector with finite orbit is fixed by a positive power of every conjugate of that unipotent. Since $(I+N)^j=I+jN$ in characteristic zero, it belongs to $\ker N$, $\ker(NA_1)$ and $\ker(NA_2)$. The equations are $u=0$, $6g+w=0$, $-w=0$, forcing zero. The coefficient matrix of these three equations has determinant $6$.
\end{enumerate}
\end{proof}

